package com.bank.capacity;

import java.util.logging.*;

public class CapacityDemo {
    private static final Logger log = Logger.getLogger("Capacity");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CapacityPlanner planner = new CapacityPlanner();

        // Business inputs for the statement feature
        long dailyRequests  = 100_000_000L;   // 100M statement views/day
        int  peakFactor     = 5;
        long bytesPerRecord = 300L;            // one transaction record
        long recordsPerDay  = 10_000_000L;     // 10M transactions/day
        long retentionDays  = 7L * 365L;       // 7 years
        long responseBytes  = 200L * 1024L;    // 200 KB per statement
        long serverCapacityQps = 1000L;        // assumed per-server QPS

        PlanReport report = new PlanReport();
        report.peakQps      = planner.estimateQps(dailyRequests, peakFactor);
        report.totalBytes   = planner.estimateStorage(bytesPerRecord, recordsPerDay, retentionDays);
        report.peakBps      = planner.estimateBandwidth(responseBytes, report.peakQps);
        report.serverCount  = planner.estimateServers(report.peakQps, serverCapacityQps);

        report.print(log);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
