package com.bank.capacity;

import java.util.logging.Logger;

public class PlanReport {
    public long peakQps;
    public long totalBytes;
    public long peakBps;
    public long serverCount;

    public void print(Logger log) {
        log.info(() -> "Peak QPS           : " + peakQps);
        log.info(() -> "Total storage      : " + gb(totalBytes) + " GB");
        log.info(() -> "Peak bandwidth     : " + mb(peakBps) + " MB/s");
        log.info(() -> "Servers required   : " + serverCount);
    }
    private long gb(long bytes) { return bytes / (1024L*1024L*1024L); }
    private long mb(long bytes) { return bytes / (1024L*1024L); }
}
